<script setup lang="ts">
import { matchDate } from '../services/format';
import { computed, onMounted, ref, watch } from 'vue';
import { useClub } from '../stores/club';
import { useAuth } from '../stores/auth';
import { api, errorMessage } from '../services/api';
import StateNotice from '../components/StateNotice.vue';
import MatchCard from '../components/MatchCard.vue';
import StatChart from '../components/StatChart.vue';
const club = useClub(), auth = useAuth(); const data = ref<any>(), busy = ref(false), error = ref('');
let requestId = 0;
async function load() { const current = ++requestId; busy.value = true; error.value = ''; try { const response = await api.get('/statistics', { params: { ...club.params } }); if (current === requestId) data.value = response.data; } catch (e) { if (current === requestId) { error.value = errorMessage(e); data.value = undefined; } } finally { if (current === requestId) busy.value = false; } }
onMounted(load); watch(() => club.selectedId, load);
const chart = computed(() => ({ labels: (data.value?.recent ?? []).slice().reverse().filter((m: any) => m.status === 'FINISHED').map((m: any) => matchDate(m)), series: [{ name: 'Goles totales', data: (data.value?.recent ?? []).slice().reverse().filter((m: any) => m.status === 'FINISHED').map((m: any) => m.homeScore === null ? null : m.homeScore + m.awayScore) }] }));
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">TU CENTRO DE JUEGO</span><h1>Una mirada al <span class="accent">rendimiento.</span></h1><p>Hola, {{ auth.user?.name.split(' ')[0] }}. Esto es lo que cuentan tus datos.</p></div><button class="button subtle" :disabled="busy" @click="load"><i aria-hidden="true" class="pi pi-refresh" /> Actualizar</button></div><div v-if="data?.isDemo" class="demo-banner"><i aria-hidden="true" class="pi pi-info-circle" /> Espacio de demostración. Club, jugadores y resultados ficticios.</div><StateNotice :loading="busy" :error="error" @retry="load" /><template v-if="data && !busy && !error"><div class="hero-panel"><div><span class="pill">FOOTLAB {{ club.selected ? 'CLUB' : 'PRO' }} <span>↗</span></span><h2>El talento se ve.<br>El progreso <em>se mide.</em></h2><p>{{ club.selected?.organization.name ?? 'Explora el fútbol profesional con datos de fuentes verificables.' }}</p><RouterLink class="button primary" :to="club.selected ? '/club' : '/explore'">{{ club.selected ? 'Gestionar mi club' : 'Explorar competiciones' }} <i aria-hidden="true" class="pi pi-arrow-up-right" /></RouterLink></div><div class="hero-pitch" aria-hidden="true"><div class="pitch-half" /><div class="pitch-center" /><span v-for="(p, i) in [[25, 20], [60, 18], [42, 43], [75, 65], [25, 75], [60, 85]]" :key="i" :style="{ left: p[0] + '%', top: p[1] + '%' }">{{ String(i + 1).padStart(2, '0') }}</span></div><span class="hero-index">01 / VISTA GENERAL</span></div><div class="metric-grid"><article v-for="m in [{ label: 'Jugadores', value: data.players, icon: 'pi-users', caption: 'Perfiles registrados' }, { label: 'Equipos', value: data.teams, icon: 'pi-shield', caption: 'En tu espacio' }, { label: 'Partidos', value: data.matches, icon: 'pi-calendar', caption: 'Historial y calendario' }, { label: 'Goles', value: data.goals, icon: 'pi-bullseye', caption: 'En resultados finalizados' }]" :key="m.label" class="metric-card"><div><span>{{ m.label }}</span><i aria-hidden="true" :class="['pi', m.icon]" /></div><strong>{{ m.value ?? '—' }}</strong><small>{{ m.caption }}</small></article></div><div class="dashboard-grid"><section class="panel"><div class="section-heading"><div><span class="eyebrow">EL JUEGO RECIENTE</span><h2>Últimos partidos</h2></div><RouterLink class="text-link" to="/club">Ver club <i aria-hidden="true" class="pi pi-arrow-right" /></RouterLink></div><div class="match-list"><MatchCard v-for="m in data.recent" :key="m.id" :match="m" :organization-id="club.selectedId || undefined" /><StateNotice :empty="!data.recent.length" /></div></section><section class="panel"><div class="section-heading"><div><span class="eyebrow">EN LOS RESULTADOS</span><h2>Goles por partido</h2></div><i aria-hidden="true" class="pi pi-chart-bar muted" /></div><StatChart v-if="chart.labels.length" :labels="chart.labels" :series="chart.series" label="Goles totales en los últimos partidos finalizados" /><StateNotice v-else empty /><p class="chart-footnote">Resultados registrados. No incluye partidos pendientes.</p></section></div><RouterLink class="lab-callout" to="/analyze"><span class="lab-icon"><i aria-hidden="true" class="pi pi-sliders-h" /></span><div><span class="eyebrow">FOOTLAB LAB</span><h3>Dos jugadores. Una nueva perspectiva.</h3><p>Compara sus números, su evolución y su impacto por 90 minutos.</p></div><i aria-hidden="true" class="pi pi-arrow-up-right" /></RouterLink></template></section></template>
